        let mut state = StateStore::new(&project);

        assert!(!state.is_step_complete("test"));

        state.record_step_result(
            "test",
            StepStatus::Success,
            std::time::Duration::from_secs(1),
        );

        assert!(state.is_step_complete("test"));
    }

    #[test]
    fn is_step_complete_false_for_failed() {
