            TrustPolicy::Reject,
            &trust_path,
            &mut ui,
        )
        .unwrap();

        assert_eq!(config.app_name, Some("MyApp".to_string()));
        // No prompts should have been shown
        assert!(ui.prompts_shown().is_empty());
    }

