        let decoded = percent_decode(&encoded).unwrap();
        assert_eq!(decoded, original);
    }

    #[test]
    fn percent_decode_handles_plus_as_space() {
        assert_eq!(percent_decode("hello+world").unwrap(), "hello world");
    }

